<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>The Texas Architect</title>
<style>
  body {
    font-family: serif;
    margin: 0;
    padding: 40px;
    background-color: #f4f1ea;
    color: #222;
  }
  .page-container {
    max-width: 850px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
  }
  .main-content {
    display: flex;
    gap: 30px;
  }
  .left-column {
    flex: 0 0 32%;
    border-right: 2px solid #222;
    padding-right: 20px;
    font-family: sans-serif;
    font-size: 10px;
    line-height: 1.3;
  }
  .right-column {
    flex: 1;
    padding-left: 10px;
  }
  .center-text {
    text-align: center;
  }
  .bold {
    font-weight: bold;
  }
  .italic {
    font-style: italic;
  }
  .left-col-section {
    margin-bottom: 15px;
  }
  .small-text {
    font-size: 8px;
    text-align: justify;
    margin-bottom: 10px;
    line-height: 1.2;
  }
  .address {
    text-align: center;
    font-size: 10px;
    margin-bottom: 15px;
  }
  .officers-list, .directors-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }
  .list-item {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
  }
  .list-item span:first-child {
    text-align: left;
  }
  .list-item span:last-child {
    text-align: right;
  }
  .header-logo {
    display: flex;
    align-items: center;
    margin-bottom: 50px;
  }
  .placeholder {
    background-color: #ddd;
    border: 1px dashed #999;
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: sans-serif;
    font-size: 12px;
    color: #666;
  }
  .logo-placeholder {
    width: 110px;
    height: 65px;
    margin-right: 15px;
  }
  .title-text {
    font-family: sans-serif;
    font-size: 44px;
    font-weight: 900;
    line-height: 0.85;
    letter-spacing: 1px;
  }
  .title-text .outline {
    -webkit-text-stroke: 1.5px #222;
    color: transparent;
  }
  .article-title {
    font-size: 16px;
    font-weight: bold;
    text-align: center;
    margin-bottom: 20px;
    letter-spacing: 1px;
  }
  .article-subtitle {
    font-size: 15px;
    text-align: center;
    margin-bottom: 50px;
